    describe('executeAsyncMergeQuery', () => {
        const mergeQuery = {
            sources: [],
            joinKey: [],
            joinType: 'full',
            tableCalculations: [],
            limit: 500,
        } as never;

        test('returns validation errors without starting execution', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const trackAccount = vi.spyOn(analyticsMock, 'trackAccount');
            vi.spyOn(service, 'compileMergeQuery').mockResolvedValue({
                coreSql: null,
                typedColumns: null,
                terminalWrapper: null,
                sorts: [],
                errors: [
                    { kind: MergeQueryErrorKind.FAN_OUT, message: 'Fan-out' },
                ],
                parameterReferences: ['date'],
                fieldOrigins: {},
            } as never);
            const result = await service.executeAsyncMergeQuery({
                account: sessionAccount,
                projectUuid,
                mergeQuery,
                context: QueryExecutionContext.EXPLORE,
                mode: { type: 'interactive' },
            });

            expect(service.compileMergeQuery).toHaveBeenCalledTimes(1);
            expect(result).toMatchObject({
                outcome: 'refused',
                parameterReferences: ['date'],
                errors: [{ message: 'Fan-out' }],
            });
            expect(trackAccount).toHaveBeenCalledWith(sessionAccount, {
                event: 'merge_query.refused',
                properties: expect.objectContaining({
                    projectId: projectUuid,
                    context: QueryExecutionContext.EXPLORE,
                    joinType: 'full',
                    kind: MergeQueryErrorKind.FAN_OUT,
                    kinds: [MergeQueryErrorKind.FAN_OUT],
                    refusalCount: 1,
                    queryId: null,
                }),
            });
            trackAccount.mockRestore();
        });

        test('uses an explicit pivot configuration before a chart-derived layout', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const pivotConfiguration: PivotConfiguration = {
                indexColumn: [
                    { reference: 'orders_date', type: VizIndexType.TIME },
                ],
                valuesColumns: [
                    {
                        reference: 'orders_count',
                        aggregation: VizAggregationOptions.ANY,
                    },
                ],
                groupByColumns: [{ reference: 'orders_status' }],
                sortBy: undefined,
            };
            const executeInternal = vi
                .spyOn(service as AnyType, 'executeAsyncMergeQueryInternal')
                .mockResolvedValue({ outcome: 'started', query: {} });

            await service.executeAsyncMergeQuery({
                account: sessionAccount,
                projectUuid,
                mergeQuery,
                context: QueryExecutionContext.EXPLORE,
                mode: { type: 'interactive' },
                chart: {
                    chartConfig: { type: ChartType.TABLE, config: {} },
                    pivotConfig: { columns: ['source_chart_series'] },
                },
                pivotConfiguration,
            });

            expect(executeInternal).toHaveBeenCalledWith(
                expect.objectContaining({
                    pivotInput: {
                        type: 'resolved',
                        configuration: pivotConfiguration,
                    },
                }),
            );
        });
    });

    describe('getJwtDashboardQueryContext', () => {
        const buildDashboardEmbedAccount = () =>
            ({
                ...buildAccount({
                    accountType: 'jwt',
                    userType: 'anonymous',
                }),
                access: {
                    content: {
                        type: 'dashboard',
                        dashboardUuid: 'embedded-dashboard-uuid',
                    },
                },
                authentication: {
                    type: 'jwt',
                    data: {},
                },
            }) as unknown as Account;

        const buildEmbedWriteAccount = () =>
            ({
                ...buildAccount({
                    accountType: 'jwt',
                    userType: 'anonymous',
                }),
                access: {
                    content: {
                        type: 'dashboard',
                        dashboardUuid: 'embedded-dashboard-uuid',
                    },
                },
                authentication: {
                    type: 'jwt',
                    data: {
                        writeActions: {
                            spaceUuid: 'write-space-uuid',
                        },
                    },
                },
                embedWriteUser: {
                    ...sessionAccount.user,
                    ability: new Ability<PossibleAbilities>([
                        {
                            subject: 'Dashboard',
                            action: 'view',
                            conditions: {
                                projectUuid,
                                inheritsFromOrgOrProject: true,
                            },
                        },
                    ]),
                },
            }) as unknown as Account;

        test('uses the embedded dashboard for non-write JWTs', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock, {
                dashboardModel: {
                    getByIdOrSlug: vi.fn(),
                } as unknown as DashboardModel,
            });

            const result = await (
                service as unknown as JwtDashboardQueryContextTestService
            ).getJwtDashboardQueryContext(
                buildDashboardEmbedAccount(),
                projectUuid,
                'request-dashboard-uuid',
            );

            expect(result.dashboardUuid).toBe('embedded-dashboard-uuid');
            expect(service.dashboardModel.getByIdOrSlug).not.toHaveBeenCalled();
        });

        test('uses request dashboard when it belongs to the embed write space', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock, {
                dashboardModel: {
                    getByIdOrSlug: vi.fn(async () => ({
                        uuid: 'request-dashboard-uuid',
                        name: 'Request dashboard',
                        organizationUuid: projectSummary.organizationUuid,
                        projectUuid,
                        spaceUuid: 'write-space-uuid',
                    })),
                } as unknown as DashboardModel,
            });

            const result = await (
                service as unknown as JwtDashboardQueryContextTestService
            ).getJwtDashboardQueryContext(
                buildEmbedWriteAccount(),
                projectUuid,
                'request-dashboard-uuid',
            );

            expect(result.dashboardUuid).toBe('request-dashboard-uuid');
        });

        test('falls back to embedded dashboard when request dashboard is outside the embed write space', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock, {
                dashboardModel: {
                    getByIdOrSlug: vi.fn(async () => ({
                        uuid: 'request-dashboard-uuid',
                        name: 'Request dashboard',
                        organizationUuid: projectSummary.organizationUuid,
                        projectUuid,
                        spaceUuid: 'other-space-uuid',
                    })),
                } as unknown as DashboardModel,
            });

            const result = await (
                service as unknown as JwtDashboardQueryContextTestService
            ).getJwtDashboardQueryContext(
                buildEmbedWriteAccount(),
                projectUuid,
                'request-dashboard-uuid',
            );

            expect(result.dashboardUuid).toBe('embedded-dashboard-uuid');
        });
    });

    describe('checkDashboardChartQueryPermissions with source spaces', () => {
        type ChartQueryPermissionsTestService = {
            checkDashboardChartQueryPermissions: (
                account: Account,
                projectUuid: string,
                savedChartUuid: string,
                space: { uuid: string; organizationUuid: string },
                owningDashboardUuid: string | null,
            ) => Promise<void>;
            assertSavedChartViewAccessForUser: (...args: unknown[]) => unknown;
        };

        const buildSourceSpaceAccount = () =>
            ({
                isJwtUser: () => true,
                access: {
                    content: {
                        type: 'dashboard',
                        dashboardUuid: 'embedded-dashboard-uuid',
                    },
                },
                authentication: {
                    type: 'jwt',
                    data: {
                        content: {
                            type: 'dashboard',
                            dashboardUuid: 'embedded-dashboard-uuid',
                        },
                        writeActions: {
                            spaceUuid: 'write-space-uuid',
                            sourceSpaceUuids: ['source-space-uuid'],
                        },
                    },
                },
                embedWriteUser: {
                    ...sessionAccount.user,
                    ability: new Ability<PossibleAbilities>([
                        { subject: 'Project', action: 'view' },
                    ]),
                },
                user: { ability: new Ability<PossibleAbilities>([]) },
            }) as unknown as Account;

        const buildService = () => {
            const checkEmbedPermissions = vi.fn(async () => {
                throw new ForbiddenError('Chart is not embedded');
            });
            const service = getMockedAsyncQueryService(lightdashConfigMock, {
                permissionsService: {
                    checkEmbedPermissions,
                } as unknown as PermissionsService,
            } as never) as unknown as ChartQueryPermissionsTestService;
            const assertViewAccess = vi
                .spyOn(service, 'assertSavedChartViewAccessForUser')
                .mockResolvedValue(undefined);
            return { service, checkEmbedPermissions, assertViewAccess };
        };

        test('authorizes a source-space chart through the write actor', async () => {
            const { service, checkEmbedPermissions, assertViewAccess } =
                buildService();

            await service.checkDashboardChartQueryPermissions(
                buildSourceSpaceAccount(),
                projectUuid,
                'source-chart-uuid',
                {
                    uuid: 'source-space-uuid',
                    organizationUuid: projectSummary.organizationUuid,
                },
                null,
            );

            expect(assertViewAccess).toHaveBeenCalledWith(
                expect.objectContaining({ userUuid: sessionAccount.user.id }),
                expect.objectContaining({
                    spaceUuid: 'source-space-uuid',
                    savedChartUuid: 'source-chart-uuid',
                }),
            );
            expect(checkEmbedPermissions).not.toHaveBeenCalled();
        });

        test('keeps the dashboard check for charts outside the token spaces', async () => {
            const { service, checkEmbedPermissions, assertViewAccess } =
                buildService();

            await expect(
                service.checkDashboardChartQueryPermissions(
                    buildSourceSpaceAccount(),
                    projectUuid,
                    'other-chart-uuid',
                    {
                        uuid: 'other-space-uuid',
                        organizationUuid: projectSummary.organizationUuid,
                    },
                    null,
                ),
            ).rejects.toThrow(ForbiddenError);
            expect(checkEmbedPermissions).toHaveBeenCalled();
            expect(assertViewAccess).not.toHaveBeenCalled();
        });
    });

