    describe('executeMetricQueryAndGetResults', () => {
        it('does not submit a query after cancellation', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            service.executeAsyncMetricQuery = vi.fn();
            const controller = new AbortController();
            controller.abort(new Error('Run timed out'));
            await expect(
                service.executeMetricQueryAndGetResults(
                    {
                        account: sessionAccount,
                        projectUuid,
                        metricQuery: metricQueryMock,
                        context: QueryExecutionContext.AI,
                    },
                    { abortSignal: controller.signal },
                ),
            ).rejects.toThrow('Run timed out');
            expect(service.executeAsyncMetricQuery).not.toHaveBeenCalled();
        });

        it.each([
            QueryHistoryStatus.QUEUED,
            QueryHistoryStatus.EXECUTING,
            QueryHistoryStatus.READY,
        ])(
            'cancels unfinished warehouse work after an abort (%s)',
            async (status) => {
                const service = getMockedAsyncQueryService(lightdashConfigMock);
                const controller = new AbortController();
                service.executeAsyncMetricQuery = vi.fn().mockResolvedValue({
                    queryUuid: 'query-uuid',
                    cacheMetadata: { cacheHit: false },
                    fields: {},
                });
                service.pollForQueryCompletion = vi.fn(
                    async ({ abortSignal }) => {
                        expect(abortSignal).toBe(controller.signal);
                        controller.abort(new Error('Run timed out'));
                        throw controller.signal.reason;
                    },
                );
                service.queryHistoryModel.get = vi
                    .fn()
                    .mockResolvedValue({ status });
                service.cancelAsyncQuery = vi.fn().mockResolvedValue(undefined);
                await expect(
                    service.executeMetricQueryAndGetResults(
                        {
                            account: sessionAccount,
                            projectUuid,
                            metricQuery: metricQueryMock,
                            context: QueryExecutionContext.AI,
                        },
                        { abortSignal: controller.signal },
                    ),
                ).rejects.toThrow('Run timed out');
                if (status === QueryHistoryStatus.READY)
                    expect(service.cancelAsyncQuery).not.toHaveBeenCalled();
                else
                    expect(service.cancelAsyncQuery).toHaveBeenCalledWith({
                        account: sessionAccount,
                        projectUuid,
                        queryUuid: 'query-uuid',
                    });
            },
        );

        it.each([false, true])(
            'retries normal execution once if a reused result disappears (aborted: %s)',
            async (aborted) => {
                const service = getMockedAsyncQueryService(lightdashConfigMock);
                const controller = new AbortController();
                service.executeAsyncMetricQuery = vi
                    .fn()
                    .mockResolvedValueOnce({
                        queryUuid: 'previous',
                        fields: {},
                        cacheMetadata: { cacheHit: true },
                    })
                    .mockResolvedValue({
                        queryUuid: 'fresh',
                        fields: {},
                        cacheMetadata: { cacheHit: false },
                    });
                service.pollForQueryCompletion = vi
                    .fn()
                    .mockResolvedValue({ status: QueryHistoryStatus.READY });
                const getReady = vi
                    .fn()
                    .mockImplementationOnce(async () => {
                        if (aborted) controller.abort(new Error('Cancelled'));
                        throw new ResultsExpiredError();
                    })
                    .mockResolvedValue({
                        rows: [{ count: 42 }],
                        fields: {},
                        cacheMetadata: { cacheHit: false },
                    });
                (service as AnyType).getReadyQueryResults = getReady;
                const args = {
                    account: sessionAccount,
                    projectUuid,
                    metricQuery: metricQueryMock,
                    context: QueryExecutionContext.AI,
                };
                const result = service.executeMetricQueryAndGetResults(
                    args,
                    { abortSignal: controller.signal },
                    'previous',
                );
                if (aborted) {
                    await expect(result).rejects.toThrow('Cancelled');
                    expect(
                        service.executeAsyncMetricQuery,
                    ).toHaveBeenCalledTimes(1);
                } else {
                    await expect(result).resolves.toMatchObject({
                        queryUuid: 'fresh',
                        rows: [{ count: 42 }],
                    });
                    expect(
                        service.executeAsyncMetricQuery,
                    ).toHaveBeenNthCalledWith(2, args);
                }
            },
        );

        it('does not retry again if the fresh result also expires', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            service.executeAsyncMetricQuery = vi
                .fn()
                .mockResolvedValueOnce({
                    queryUuid: 'previous',
                    fields: {},
                    cacheMetadata: { cacheHit: true },
                })
                .mockResolvedValueOnce({
                    queryUuid: 'fresh',
                    fields: {},
                    cacheMetadata: { cacheHit: false },
                });
            service.pollForQueryCompletion = vi.fn().mockResolvedValue({
                status: QueryHistoryStatus.READY,
            });
            (service as AnyType).getReadyQueryResults = vi
                .fn()
                .mockRejectedValue(new ResultsExpiredError());

            await expect(
                service.executeMetricQueryAndGetResults(
                    {
                        account: sessionAccount,
                        projectUuid,
                        metricQuery: metricQueryMock,
                        context: QueryExecutionContext.AI,
                    },
                    undefined,
                    'previous',
                ),
            ).rejects.toBeInstanceOf(ResultsExpiredError);
            expect(service.executeAsyncMetricQuery).toHaveBeenCalledTimes(2);
        });

        it('does not rerun a reused query after an unrelated result-read failure', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            service.executeAsyncMetricQuery = vi.fn().mockResolvedValue({
                queryUuid: 'previous',
                fields: {},
                cacheMetadata: { cacheHit: true },
            });
            service.pollForQueryCompletion = vi.fn().mockResolvedValue({
                status: QueryHistoryStatus.READY,
            });
            (service as AnyType).getReadyQueryResults = vi
                .fn()
                .mockRejectedValue(new Error('Result storage unavailable'));

            await expect(
                service.executeMetricQueryAndGetResults(
                    {
                        account: sessionAccount,
                        projectUuid,
                        metricQuery: metricQueryMock,
                        context: QueryExecutionContext.AI,
                    },
                    undefined,
                    'previous',
                ),
            ).rejects.toThrow('Result storage unavailable');
            expect(service.executeAsyncMetricQuery).toHaveBeenCalledOnce();
        });

        it('preserves the query UUID with the ready results', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            service.executeAsyncMetricQuery = vi.fn().mockResolvedValue({
                queryUuid: '11111111-1111-4111-8111-111111111111',
                cacheMetadata: { cacheHit: false },
                fields: {},
            });
            service.pollForQueryCompletion = vi.fn().mockResolvedValue({
                status: QueryHistoryStatus.READY,
            } as QueryHistory);
            const getReadyQueryResults = vi.fn().mockResolvedValue({
                rows: [{ a_dim1: 'one', a_met1: 1 }],
                cacheMetadata: { cacheHit: false },
                fields: {},
                pivotDetails: null,
                displayTimezone: null,
            });
            (service as AnyType).getReadyQueryResults = getReadyQueryResults;

            const result = await service.executeMetricQueryAndGetResults({
                account: sessionAccount,
                projectUuid,
                metricQuery: metricQueryMock,
                context: QueryExecutionContext.AI,
            });

            expect(result.queryUuid).toBe(
                '11111111-1111-4111-8111-111111111111',
            );
            expect(getReadyQueryResults).toHaveBeenCalledWith(
                expect.objectContaining({
                    queryUuid: '11111111-1111-4111-8111-111111111111',
                }),
            );
        });

        it('extends result availability without shortening longer retention', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const { queryHistoryModel } = service as AnyType;
            const expiresAt = new Date('2026-09-01T00:00:00.000Z');
            queryHistoryModel.get = vi.fn().mockResolvedValue({
                resultsFileName: 'results.jsonl',
                resultsExpiresAt: new Date('2026-08-01T00:00:00.000Z'),
            });
            queryHistoryModel.update = vi.fn().mockResolvedValue(1);

            await service.extendQueryResultsExpiration({
                account: sessionAccount,
                projectUuid,
                queryUuid: '11111111-1111-4111-8111-111111111111',
                expiresAt,
            });

            expect(queryHistoryModel.update).toHaveBeenCalledWith(
                '11111111-1111-4111-8111-111111111111',
                projectUuid,
                { results_expires_at: expiresAt },
                sessionAccount,
            );

            queryHistoryModel.get.mockResolvedValue({
                resultsFileName: 'results.jsonl',
                resultsExpiresAt: new Date('2026-10-01T00:00:00.000Z'),
            });
            queryHistoryModel.update.mockClear();

            await service.extendQueryResultsExpiration({
                account: sessionAccount,
                projectUuid,
                queryUuid: '11111111-1111-4111-8111-111111111111',
                expiresAt,
            });

            expect(queryHistoryModel.update).not.toHaveBeenCalled();
        });
    });

