        test.each([
            'reuse',
            'scope-change',
            'identity-mismatch',
            'expired',
            'denied',
            'ordinary',
            'principal',
            'slot',
            'marked-agent',
            'scoped-agent',
            'unknown-client-agent',
            'person-reuse',
            'person-incompatible',
        ] as const)(
            'presentation reuse keeps current authorization and compilation: %s',
            async (scenario) => {
                const service = getMockedAsyncQueryService(lightdashConfigMock);
                if (
                    scenario === 'marked-agent' ||
                    scenario === 'scoped-agent' ||
                    scenario === 'unknown-client-agent' ||
                    scenario === 'person-reuse' ||
                    scenario === 'person-incompatible'
                )
                    vi.mocked(service.featureFlagModel.get).mockImplementation(
                        async ({ featureFlagId }) => ({
                            id: featureFlagId,
                            enabled:
                                featureFlagId === FeatureFlags.AgentIdentity,
                        }),
                    );
                const access = vi
                    .spyOn(service, 'getExploreWithUserAccessControls')
                    .mockResolvedValue({
                        explore: validExplore,
                        userAccessControls: {
                            userAttributes: {},
                            intrinsicUserAttributes: {},
                        },
                    });
                if (scenario === 'principal' || scenario === 'slot') {
                    vi.spyOn(
                        service as AnyType,
                        'getWarehouseCredentialsWithConnection',
                    ).mockResolvedValue({
                        warehouseCredentials: warehouseCredentialsMock,
                        warehouseConnectionUuid: null,
                        connectionRoute: {
                            route: 'single',
                            originalWarehouseConnectionUuid: null,
                        },
                        aiPlan:
                            scenario === 'slot'
                                ? {
                                      ...aiServiceAccountPlanMock,
                                      agentIdentity: {
                                          sub: 'service_account:subject',
                                          subject: {
                                              type: 'service_account',
                                              uuid: 'subject',
                                          },
                                          act: {
                                              sub: 'mcp:unknown',
                                              surface: 'mcp',
                                              client_id: null,
                                          },
                                      },
                                  }
                                : {
                                      ...aiExecutionPlanMock,
                                      agentIdentity: {
                                          sub: 'user:subject',
                                          subject: {
                                              type: 'user',
                                              uuid: 'subject',
                                          },
                                          act: {
                                              sub: 'in_app_agent:lightdash-chat',
                                              surface: 'in_app_agent',
                                              client_id: 'lightdash-chat',
                                          },
                                      },
                                  },
                    });
                }
                if (scenario === 'denied')
                    access.mockRejectedValue(new ForbiddenError());
                service['getWarehouseCredentials'] = vi
                    .fn()
                    .mockResolvedValue(warehouseClientMock.credentials);
                service.combineParameters = vi
                    .fn()
                    .mockResolvedValue(undefined);
                const composer = createQueryComposerMock({
                    sql:
                        scenario === 'scope-change'
                            ? 'SELECT * FROM test WHERE region = 2'
                            : 'SELECT * FROM test',
                    userAccessControls: {
                        userAttributes: {},
                        intrinsicUserAttributes: {},
                    },
                    availableParameterDefinitions: {},
                });
                const prepare = vi
                    .spyOn(
                        service as unknown as {
                            prepareMetricQueryAsyncQueryArgs: () => Promise<QueryComposer>;
                        },
                        'prepareMetricQueryAsyncQueryArgs',
                    )
                    .mockResolvedValue(composer);
                const execute = vi.fn().mockResolvedValue({
                    queryUuid: 'new',
                    cacheMetadata: { cacheHit: false },
                });
                service['executeAsyncQuery'] = execute;
                const history = vi
                    .spyOn(service, 'getAsyncQueryHistory')
                    .mockResolvedValue({
                        queryUuid: 'previous',
                        status: QueryHistoryStatus.READY,
                        compiledSql: 'SELECT * FROM test',
                        usedParameters: {},
                        createdByUserUuid: sessionAccount.user.id,
                        resultsFileName: 'results.jsonl',
                        createdAt: new Date(),
                        resultsExpiresAt: new Date(
                            Date.now() +
                                (scenario === 'expired' ? -60_000 : 60_000),
                        ),
                    } as QueryHistory);
                if (
                    scenario === 'identity-mismatch' ||
                    scenario === 'person-incompatible'
                )
                    history.mockRejectedValue(
                        new AiAccessRefusedError(
                            AiAccessRefusalReason.RESULT_NOT_AGENT_PRODUCED,
                        ),
                    );
                const submit = () =>
                    service.executeAsyncMetricQuery(
                        {
                            account: sessionAccount,
                            projectUuid,
                            metricQuery: metricQueryMock,
                            context:
                                scenario === 'person-reuse' ||
                                scenario === 'person-incompatible'
                                    ? QueryExecutionContext.EXPLORE
                                    : QueryExecutionContext.AI,
                        },
                        scenario === 'ordinary' ? undefined : 'previous',
                    );
                const result =
                    scenario === 'scoped-agent' ||
                    scenario === 'marked-agent' ||
                    scenario === 'unknown-client-agent'
                        ? agentExecutionContext.run(
                              createAgentExecutionContext({
                                  account: sessionAccount,
                                  agentUuid: null,
                                  agentIdentityEnabled: true,
                                  surface: AgentActorSurface.MCP,
                                  clientId:
                                      scenario === 'unknown-client-agent'
                                          ? null
                                          : 'trusted-client',
                              }),
                              submit,
                          )
                        : submit();
                if (scenario === 'denied') {
                    await expect(result).rejects.toThrow(ForbiddenError);
                    expect(history).not.toHaveBeenCalled();
                    expect(execute).not.toHaveBeenCalled();
                    return;
                }
                const resolved = await result;
                expect(resolved.queryUuid).toBe(
                    scenario === 'reuse' || scenario === 'person-reuse'
                        ? 'previous'
                        : 'new',
                );
                expect(resolved.cacheMetadata.queryReuseHit).toBe(
                    scenario === 'reuse' || scenario === 'person-reuse'
                        ? true
                        : undefined,
                );
                expect(access).toHaveBeenCalled();
                expect(prepare).toHaveBeenCalled();
                expect(execute).toHaveBeenCalledTimes(
                    scenario === 'reuse' || scenario === 'person-reuse' ? 0 : 1,
                );
                if (scenario === 'principal' || scenario === 'slot') {
                    expect(execute).toHaveBeenCalledWith(
                        expect.objectContaining({
                            agentIdentity: expect.objectContaining({
                                sub:
                                    scenario === 'slot'
                                        ? 'service_account:subject'
                                        : 'user:subject',
                            }),
                            aiPrincipalUuid:
                                scenario === 'slot'
                                    ? aiServiceAccountPlanMock.identityUuid
                                    : aiExecutionPlanMock.identityUuid,
                        }),
                        expect.anything(),
                    );
                }
                if (
                    scenario === 'ordinary' ||
                    scenario === 'principal' ||
                    scenario === 'slot' ||
                    scenario === 'marked-agent' ||
                    scenario === 'scoped-agent' ||
                    scenario === 'unknown-client-agent'
                )
                    expect(history).not.toHaveBeenCalled();
                else
                    expect(history).toHaveBeenCalledWith({
                        account: sessionAccount,
                        projectUuid,
                        queryUuid: 'previous',
                        ...(scenario === 'person-reuse' ||
                        scenario === 'person-incompatible'
                            ? {
                                  reader: {
                                      kind: 'person',
                                      authMethod: 'session',
                                  },
                              }
                            : {}),
                    });
            },
        );

