    describe('analytics cached-result boundaries', () => {
        afterEach(() => {
            projectModel.getSummary.mockResolvedValue(projectSummary);
            vi.mocked(
                analyticsClient.assertAnalyticsProjectEnabled,
            ).mockRestore();
        });
        test.each(['disabled', 'non-admin', 'cross-org'] as const)(
            'blocks every result/history/export surface for %s access',
            async (reason) => {
                const service = getMockedAsyncQueryService(lightdashConfigMock);
                service.exportsStorageClient = {
                    isEnabled: () => true,
                } as FileStorageClient;
                const account = buildAccount();
                account.user.ability = new Ability<PossibleAbilities>([
                    { action: 'view', subject: 'Project' },
                ]);
                vi.spyOn(projectModel, 'getSummary').mockResolvedValue({
                    ...projectSummary,
                    organizationUuid:
                        reason === 'cross-org'
                            ? 'other-org'
                            : account.organization.organizationUuid!,
                    provisioningSource: 'analytics',
                });
                vi.spyOn(
                    analyticsClient,
                    'assertAnalyticsProjectEnabled',
                ).mockImplementation(async () => {
                    if (reason === 'disabled')
                        throw new ForbiddenError('analytics disabled');
                });
                const args = {
                    account,
                    projectUuid,
                    queryUuid: 'existing-query',
                    type: DownloadFileType.CSV,
                    accessMode:
                        PersistentDownloadFileAccessMode.AUTHENTICATED_CREATOR as const,
                };
                const expected = {
                    disabled: 'analytics disabled',
                    'cross-org': 'another organization',
                    'non-admin': 'administration',
                }[reason];
                await expect(
                    service.getAsyncQueryHistory(args),
                ).rejects.toThrow(expected);
                await expect(service.getResultsStream(args)).rejects.toThrow(
                    expected,
                );
                await expect(
                    service.getQueryHistoryList({
                        ...args,
                        filters: {},
                        paginateArgs: { page: 1, pageSize: 10 },
                    }),
                ).rejects.toThrow(expected);
                await expect(
                    service.scheduleDownloadAsyncQueryResults(args),
                ).rejects.toThrow(expected);
                await expect(service.download(args)).rejects.toThrow(expected);
                expect(service.queryHistoryModel.get).not.toHaveBeenCalled();
                await expect(
                    service.getAsyncQueryResults(args),
                ).rejects.toThrow(expected);
                expect(projectModel.getSummary).toHaveBeenLastCalledWith(
                    projectUuid,
                );
            },
        );
    });

    describe('getAsyncQueryHistory', () => {
        const createQueryHistory = (): QueryHistory =>
            ({
                queryUuid: 'test-query-uuid',
                projectUuid,
                organizationUuid: projectSummary.organizationUuid,
                metricQuery: metricQueryMock,
            }) as QueryHistory;

        it.each([QueryExecutionContext.AI, QueryExecutionContext.MCP_RUN_SQL])(
            'preserves a typed identity refusal when polling %s history',
            async (context) => {
                const service = getMockedAsyncQueryService(lightdashConfigMock);
                const account = buildAccount();
                account.user.ability = new Ability<PossibleAbilities>([
                    { action: 'view', subject: 'Project' },
                ]);
                const history = { ...createQueryHistory(), context };
                const refusal = new AiAccessRefusedError(
                    AiAccessRefusalReason.NEEDS_SIGN_IN,
                );
                const assertCanReadResults = vi.fn().mockRejectedValue(refusal);
                Object.assign(service, {
                    aiAccessService: { assertCanReadResults },
                });
                vi.mocked(service.queryHistoryModel.get).mockResolvedValue(
                    history,
                );
                await expect(
                    service.getAsyncQueryHistory({
                        account,
                        projectUuid,
                        queryUuid: history.queryUuid,
                    }),
                ).rejects.toBe(refusal);
                expect(assertCanReadResults).toHaveBeenCalledWith(
                    account,
                    projectUuid,
                    history,
                    expect.objectContaining({ agentProducedOnly: false }),
                );
            },
        );

        it('allows caller-owned query history with explore-level access', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const account = buildAccount();
            account.user.ability = new Ability<PossibleAbilities>([
                { action: 'view', subject: 'Explore' },
            ]);
            const queryHistory = createQueryHistory();

            (
                service.queryHistoryModel.get as import('vitest').Mock
            ).mockResolvedValue(queryHistory);

            await expect(
                service.getAsyncQueryHistory({
                    account,
                    projectUuid,
                    queryUuid: 'test-query-uuid',
                }),
            ).resolves.toBe(queryHistory);
        });

        it('rejects caller-owned query history without project or explore access', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const account = buildAccount();
            account.user.ability = new Ability<PossibleAbilities>([]);

            (
                service.queryHistoryModel.get as import('vitest').Mock
            ).mockResolvedValue(createQueryHistory());

            await expect(
                service.getAsyncQueryHistory({
                    account,
                    projectUuid,
                    queryUuid: 'test-query-uuid',
                }),
            ).rejects.toThrow(ForbiddenError);
        });
    });

    describe('pollQueryHistoryUntilDeadline', () => {
        const createMockQueryHistory = (
            status: QueryHistoryStatus,
        ): QueryHistory => ({
            createdAt: new Date(),
            organizationUuid: sessionAccount.organization.organizationUuid!,
            createdByUserUuid: sessionAccount.user.id,
            createdBy: sessionAccount.user.id,
            createdByAccount: null,
            createdByActorType: 'session',
            queryUuid: 'test-query-uuid',
            projectUuid,
            status,
            error: null,
            erroredAt: null,
            metricQuery: metricQueryMock,
            context: QueryExecutionContext.MCP_RUN_SQL,
            fields: validExplore.tables.a.dimensions,
            compiledSql: 'SELECT * FROM test.table',
            warehouseQueryId: 'test-warehouse-query-id',
            warehouseQueryMetadata: null,
            requestParameters: {} as ExecuteAsyncQueryRequestParams,
            usedParameters: null,
            totalRowCount: null,
            warehouseExecutionTimeMs: null,
            defaultPageSize: 10,
            cacheKey: 'test-query-key',
            pivotConfiguration: null,
            pivotTotalColumnCount: null,
            pivotValuesColumns: null,
            resultsFileName: null,
            resultsCreatedAt: null,
            resultsUpdatedAt: null,
            resultsExpiresAt: null,
            columns: null,
            originalColumns: null,
            preAggregateCompiledSql: null,
            preAggregateExecution: null,
            preAggregateFallbackReason: null,
            processingStartedAt: null,
            agentIdentity: null,
        });

        const getPollArgs = (
            overrides: Partial<{
                deadlineMs: number;
                pollIntervalMs: number;
                signal: AbortSignal;
            }> = {},
        ) => ({
            account: sessionAccount,
            projectUuid,
            queryUuid: 'test-query-uuid',
            deadlineMs: Date.now() + 100,
            pollIntervalMs: 1,
            ...overrides,
        });

        afterEach(() => {
            vi.restoreAllMocks();
        });

        it('returns the ready query history when the query completes before the deadline', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const queuedQueryHistory = createMockQueryHistory(
                QueryHistoryStatus.QUEUED,
            );
            const readyQueryHistory = createMockQueryHistory(
                QueryHistoryStatus.READY,
            );
            const getAsyncQueryHistory = vi
                .spyOn(service, 'getAsyncQueryHistory')
                .mockResolvedValueOnce(queuedQueryHistory)
                .mockResolvedValueOnce(readyQueryHistory);

            await expect(
                service.pollQueryHistoryUntilDeadline(getPollArgs()),
            ).resolves.toBe(readyQueryHistory);

            expect(getAsyncQueryHistory).toHaveBeenCalledTimes(2);
        });

        it('returns the latest running query history when the deadline is reached', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const queuedQueryHistory = createMockQueryHistory(
                QueryHistoryStatus.QUEUED,
            );
            const getAsyncQueryHistory = vi
                .spyOn(service, 'getAsyncQueryHistory')
                .mockResolvedValueOnce(queuedQueryHistory);

            await expect(
                service.pollQueryHistoryUntilDeadline(
                    getPollArgs({ deadlineMs: Date.now() - 1 }),
                ),
            ).resolves.toBe(queuedQueryHistory);

            expect(getAsyncQueryHistory).toHaveBeenCalledTimes(1);
        });

        it.each([
            QueryHistoryStatus.CANCELLED,
            QueryHistoryStatus.ERROR,
            QueryHistoryStatus.EXPIRED,
        ])(
            'returns terminal %s query history without waiting',
            async (status) => {
                const service = getMockedAsyncQueryService(lightdashConfigMock);
                const terminalQueryHistory = createMockQueryHistory(status);
                const getAsyncQueryHistory = vi
                    .spyOn(service, 'getAsyncQueryHistory')
                    .mockResolvedValueOnce(terminalQueryHistory);

                await expect(
                    service.pollQueryHistoryUntilDeadline(getPollArgs()),
                ).resolves.toBe(terminalQueryHistory);

                expect(getAsyncQueryHistory).toHaveBeenCalledTimes(1);
            },
        );

        it('stops polling when the request is aborted', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const abortController = new AbortController();
            const queuedQueryHistory = createMockQueryHistory(
                QueryHistoryStatus.QUEUED,
            );
            const getAsyncQueryHistory = vi
                .spyOn(service, 'getAsyncQueryHistory')
                .mockResolvedValue(queuedQueryHistory);

            const pollPromise = service.pollQueryHistoryUntilDeadline(
                getPollArgs({
                    deadlineMs: Date.now() + 10_000,
                    pollIntervalMs: 10_000,
                    signal: abortController.signal,
                }),
            );
            abortController.abort();

            await expect(pollPromise).rejects.toThrow(
                'Query polling request was aborted',
            );
            expect(getAsyncQueryHistory).toHaveBeenCalledTimes(1);
        });
    });

