    describe('executeAsyncCalculateTotalFromQueryHistory over a merged result', () => {
        afterEach(() => {
            vi.restoreAllMocks();
        });

        const mergedField = (
            type: MetricType,
            { table, name }: { table: string; name: string },
        ): ItemsMap[string] =>
            ({
                fieldType: FieldType.METRIC,
                type,
                name,
                label: name,
                table,
                tableLabel: table.toUpperCase(),
                sql: '',
                hidden: false,
            }) as ItemsMap[string];

        const legQuery = (exploreName: string, metrics: string[]) => ({
            exploreName,
            dimensions: ['orders_month'],
            metrics,
            filters: {},
            sorts: [],
            limit: 500,
            tableCalculations: [],
        });

        const mergedRow = (
            joinType: 'full' | 'left' | 'inner',
            overrides: Partial<QueryHistory> = {},
        ): QueryHistory =>
            ({
                queryUuid: 'merge-join-uuid',
                projectUuid,
                organizationUuid: projectSummary.organizationUuid,
                metricQuery: {
                    exploreName: 'merge',
                    dimensions: ['merge_join_key_0'],
                    metrics: ['a_orders_total', 'b_payments_unique'],
                    filters: {},
                    sorts: [],
                    limit: 500,
                    tableCalculations: [],
                },
                fields: {
                    a_orders_total: mergedField(MetricType.SUM, {
                        table: 'a',
                        name: 'orders_total',
                    }),
                    b_payments_unique: mergedField(MetricType.COUNT_DISTINCT, {
                        table: 'b',
                        name: 'payments_unique',
                    }),
                },
                pivotConfiguration: null,
                requestParameters: {
                    context: QueryExecutionContext.EXPLORE,
                    mergeQuery: {
                        sources: [
                            {
                                id: 'a',
                                metricQuery: legQuery('orders', [
                                    'orders_total',
                                ]),
                            },
                            {
                                id: 'b',
                                metricQuery: legQuery('payments', [
                                    'payments_unique',
                                ]),
                            },
                        ],
                        joinKey: [],
                        joinType,
                        tableCalculations: [],
                        limit: 500,
                    },
                    parameters: { region: 'EU' },
                },
                ...overrides,
            }) as unknown as QueryHistory;

        const setup = (row: QueryHistory) => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            (
                service.queryHistoryModel.get as import('vitest').Mock
            ).mockResolvedValue(row);
            const submitSpy = vi
                .spyOn(QuerySourceService.prototype, 'submitQueries')
                .mockImplementation(async ({ queries }) => ({
                    queries: queries.map((query) => ({
                        nodeId: query.nodeId ?? 'anonymous',
                        sourceType: query.sourceType,
                        queryUuid: `${query.nodeId ?? 'anonymous'}-uuid`,
                        cacheHit: false,
                    })),
                }));
            return { service, submitSpy };
        };

        // The sum is exact over the merged rows; the distinct count is not,
        // but a full join keeps every payments row, so the payments query
        // collapsed to one row totals it, as a leg of the same DAG.
        it('aggregates exact columns over the merged rows and totals the rest from their own query', async () => {
            const { service, submitSpy } = setup(mergedRow('full'));

            const result =
                await service.executeAsyncCalculateTotalFromQueryHistory({
                    account: buildAccount(),
                    projectUuid,
                    queryUuid: 'merge-join-uuid',
                    kind: 'columnTotal',
                });

            expect(submitSpy).toHaveBeenCalledTimes(1);
            const args = submitSpy.mock.calls[0][0];
            expect(args.context).toBe(QueryExecutionContext.CALCULATE_TOTAL);
            expect(args.parameters).toEqual({ region: 'EU' });
            expect(args.queries).toHaveLength(2);
            expect(args.queries[0]).toMatchObject({
                sourceType: QuerySourceType.SEMANTIC_LAYER,
                nodeId: 'source_total_1',
                exploreName: 'payments',
                dimensions: [],
                metrics: ['payments_unique'],
                limit: 1,
            });
            expect(args.queries[1]).toEqual({
                sourceType: QuerySourceType.DUCKDB,
                nodeId: 'merge_totals',
                sql: [
                    'SELECT SUM("a_orders_total") AS "a_orders_total",',
                    '       (SELECT "payments_unique" FROM "source_total_1") AS "b_payments_unique"',
                    'FROM "merged_result"',
                ].join('\n'),
                references: {
                    merged_result: 'merge-join-uuid',
                    source_total_1: 'source_total_1',
                },
            });
            expect(args.plans.merge_totals.referenceLabels).toEqual({
                merged_result: 'Merged result',
                source_total_1: 'B total',
            });
            expect(result.queryUuid).toBe('merge_totals-uuid');
            expect(Object.keys(result.fields)).toEqual([
                'a_orders_total',
                'b_payments_unique',
            ]);
            expect(result.metricQuery.metrics).toEqual([
                'a_orders_total',
                'b_payments_unique',
            ]);
        });

        it('runs no leg when the join drops rows of the only source that would need one', async () => {
            const { service, submitSpy } = setup(mergedRow('inner'));

            const result =
                await service.executeAsyncCalculateTotalFromQueryHistory({
                    account: buildAccount(),
                    projectUuid,
                    queryUuid: 'merge-join-uuid',
                    kind: 'columnTotal',
                });

            const args = submitSpy.mock.calls[0][0];
            expect(args.queries.map((query) => query.nodeId)).toEqual([
                'merge_totals',
            ]);
            expect(Object.keys(result.fields)).toEqual(['a_orders_total']);
        });

        it('has nothing to total when no merged column has a total', async () => {
            const { service, submitSpy } = setup(
                mergedRow('inner', {
                    fields: {
                        b_payments_unique: mergedField(
                            MetricType.COUNT_DISTINCT,
                            { table: 'b', name: 'payments_unique' },
                        ),
                    },
                    metricQuery: {
                        exploreName: 'merge',
                        dimensions: ['merge_join_key_0'],
                        metrics: ['b_payments_unique'],
                        filters: {},
                        sorts: [],
                        limit: 500,
                        tableCalculations: [],
                    },
                } as Partial<QueryHistory>),
            );

            await expect(
                service.executeAsyncCalculateTotalFromQueryHistory({
                    account: buildAccount(),
                    projectUuid,
                    queryUuid: 'merge-join-uuid',
                    kind: 'columnTotal',
                }),
            ).rejects.toThrow(NotSupportedError);
            expect(submitSpy).not.toHaveBeenCalled();
        });

        it('does not total a pivoted merged result yet', async () => {
            const { service, submitSpy } = setup(
                mergedRow('full', {
                    pivotConfiguration: {
                        indexColumn: [],
                        valuesColumns: [],
                        groupByColumns: [{ reference: 'merge_join_key_0' }],
                        sortBy: undefined,
                    },
                } as Partial<QueryHistory>),
            );

            await expect(
                service.executeAsyncCalculateTotalFromQueryHistory({
                    account: buildAccount(),
                    projectUuid,
                    queryUuid: 'merge-join-uuid',
                    kind: 'columnTotal',
                }),
            ).rejects.toThrow(NotSupportedError);
            expect(submitSpy).not.toHaveBeenCalled();
        });
    });

    describe('executeAsyncUnboundedRerunFromQueryHistory', () => {
        afterEach(() => {
            vi.restoreAllMocks();
        });

        const mockSourceQueryHistory = (sourceLimit: number) =>
            ({
                queryUuid: 'capped-query-uuid',
                projectUuid,
                organizationUuid: projectSummary.organizationUuid,
                metricQuery: {
                    ...metricQueryMock,
                    limit: sourceLimit,
                },
                pivotConfiguration: null,
                requestParameters: {
                    context: QueryExecutionContext.SCHEDULED_DELIVERY,
                    query: metricQueryMock,
                    parameters: { region: 'EU' },
                },
            }) as unknown as QueryHistory;

        // 'all' semantics: the org's cell-based cap, computed the same way
        // for every source limit in this describe block.
        const expectedUnboundedLimit = Math.floor(
            lightdashConfigMock.query.csvCellsLimit /
                (metricQueryMock.dimensions.length +
                    metricQueryMock.metrics.length +
                    metricQueryMock.tableCalculations.length),
        );

        it('re-runs the source metricQuery with the row limit lifted, returning the applied limit', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const account = buildAccount();

            (
                service.queryHistoryModel.get as import('vitest').Mock
            ).mockResolvedValue(mockSourceQueryHistory(500));

            const runSpy = vi
                .spyOn(
                    service as unknown as {
                        runAsyncMetricQueryWithoutPermissionCheck: (
                            ...args: unknown[]
                        ) => Promise<unknown>;
                    },
                    'runAsyncMetricQueryWithoutPermissionCheck',
                )
                .mockResolvedValue({ queryUuid: 'rerun-query-uuid' } as never);

            const result =
                await service.executeAsyncUnboundedRerunFromQueryHistory({
                    account,
                    projectUuid,
                    queryUuid: 'capped-query-uuid',
                    context: QueryExecutionContext.SCHEDULED_DELIVERY,
                });

            expect(service.queryHistoryModel.get).toHaveBeenCalledWith(
                'capped-query-uuid',
                projectUuid,
                account,
            );
            expect(runSpy).toHaveBeenCalledTimes(1);
            const [runArgs] = runSpy.mock.calls[0] as [
                { metricQuery: MetricQuery; context: QueryExecutionContext },
            ];
            // The numeric cap from the capped run (500) is replaced by the
            // org's cell-based cap, not merely "not 500".
            expect(runArgs.metricQuery.limit).toBe(expectedUnboundedLimit);
            expect(runArgs.context).toBe(
                QueryExecutionContext.SCHEDULED_DELIVERY,
            );
            expect(runSpy.mock.calls[0][0]).toEqual(
                expect.objectContaining({
                    parameters: { region: 'EU' },
                    pivotConfiguration: undefined,
                }),
            );
            expect(result).toEqual({
                outcome: 'executed',
                queryUuid: 'rerun-query-uuid',
                appliedLimit: expectedUnboundedLimit,
            });
        });

        it('refuses to rerun a query whose connection was removed and runs nothing (K10)', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const account = buildAccount();
            (
                service.queryHistoryModel.get as import('vitest').Mock
            ).mockResolvedValue(mockSourceQueryHistory(500));
            const resolve = vi
                .spyOn(service.projectModel, 'resolveWarehouseCredentialRead')
                .mockRejectedValue(
                    new NotFoundError("Connection 'Finance' was removed"),
                );
            const runSpy = vi
                .spyOn(
                    service as unknown as {
                        runAsyncMetricQueryWithoutPermissionCheck: (
                            ...args: unknown[]
                        ) => Promise<unknown>;
                    },
                    'runAsyncMetricQueryWithoutPermissionCheck',
                )
                .mockResolvedValue({ queryUuid: 'rerun-query-uuid' } as never);

            await expect(
                service.executeAsyncUnboundedRerunFromQueryHistory({
                    account,
                    projectUuid,
                    queryUuid: 'capped-query-uuid',
                    context: QueryExecutionContext.SCHEDULED_DELIVERY,
                }),
            ).rejects.toThrow("Connection 'Finance' was removed");
            expect(resolve).toHaveBeenCalledWith(projectUuid, {
                kind: 'query',
                queryUuid: 'capped-query-uuid',
            });
            expect(runSpy).not.toHaveBeenCalled();
        });

        // Wide-query case: a source limit already at (or above) the org's
        // cell-based cap means rerunning can't return more rows than the
        // capped result already has — 'All Results' must never deliver less.
        it('skips execution and reports noImprovementPossible when the computed limit would not beat the source limit', async () => {
            const service = getMockedAsyncQueryService(lightdashConfigMock);
            const account = buildAccount();

            (
                service.queryHistoryModel.get as import('vitest').Mock
            ).mockResolvedValue(mockSourceQueryHistory(expectedUnboundedLimit));

            const runSpy = vi
                .spyOn(
                    service as unknown as {
                        runAsyncMetricQueryWithoutPermissionCheck: (
                            ...args: unknown[]
                        ) => Promise<unknown>;
                    },
                    'runAsyncMetricQueryWithoutPermissionCheck',
                )
                .mockResolvedValue({} as never);

            const result =
                await service.executeAsyncUnboundedRerunFromQueryHistory({
                    account,
                    projectUuid,
                    queryUuid: 'capped-query-uuid',
                    context: QueryExecutionContext.SCHEDULED_DELIVERY,
                });

            expect(runSpy).not.toHaveBeenCalled();
            expect(result).toEqual({ outcome: 'noImprovementPossible' });
        });
    });

